-- Publish professional version 2 of the four official taste trees.
-- Published version 1 rows remain immutable so existing shared results keep their original version.

UPDATE taste_tree_versions ttv
JOIN taste_trees tt ON tt.id = ttv.tree_id
SET ttv.status = 'ARCHIVED', ttv.updated_at = NOW(6)
WHERE tt.tree_type = 'OFFICIAL' AND ttv.status = 'PUBLISHED';

